function parseCompactEntry(zoneId: number, month: number, day: number, packed: string): ReferencePrayerRecord {
  const parts = packed.split('|');
  const [fajr, sunrise, dhuhr, asr, maghrib, isha] = parts.length === 6
    ? parts
    : [parts[0], '', parts[1], parts[2], parts[3], parts[4]];
  const mm = String(month).padStart(2, '0');
  const dd = String(day).padStart(2, '0');
  const referenceDate = `2026-${mm}-${dd}`;
  return {
    id: `acju-2026-z${zoneId}-${mm}-${dd}`,
    versionId: `acju-2026-official-z${zoneId}`,
    zoneId,
    referenceYear: 2026,
    referenceDate,
    month,
    day,
    fajr,
    sunrise,
    dhuhr,
    asr,
    maghrib,
    isha,
    verificationStatus: 'approved',
    isDemoSample: false,
  };
}

export function getEmbedded2026RecordsForMonth(zoneId: number, month: number): ReferencePrayerRecord[] {
  const zoneMap = ACJU_2026_TIMETABLE_COMPACT[zoneId];
  if (!zoneMap) return [];
  const mm = String(month).padStart(2, '0');
  const daysIn2026Month = new Date(Date.UTC(2026, month, 0)).getUTCDate();
  const rows: ReferencePrayerRecord[] = [];
  for (let d = 1; d <= daysIn2026Month; d++) {
    const dd = String(d).padStart(2, '0');
    const packed = zoneMap[`${mm}-${dd}`];
    if (packed) {
      rows.push(parseCompactEntry(zoneId, month, d, packed));
    }
  }
  return rows;
}

export function resolveEmbeddedDaySchedule(zoneId: number, dateISO: string): ResolvedDaySchedule {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateISO);
  if (!m) throw new Error('Invalid date format. Expected YYYY-MM-DD.');
  const month = Number(m[2]);
  const approvedRecords = getEmbedded2026RecordsForMonth(zoneId, month);
  return resolveScheduleForDate({
    targetDate: dateISO,
    zoneId,
    approvedRecords,
  });
}

export function resolveEmbeddedMonthSchedules(zoneId: number, year: number, month: number): ResolvedDaySchedule[] {
  const approvedRecords = getEmbedded2026RecordsForMonth(zoneId, month);
  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
  const days: ResolvedDaySchedule[] = [];
  for (let d = 1; d <= daysInMonth; d++) {
    const iso = `${year}-${String(month).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    days.push(
      resolveScheduleForDate({
        targetDate: iso,
        zoneId,
        approvedRecords,
      })
    );
  }
  return days;
}
